// Fetches dynamic articles generated by BlogPilot from the CRM API.

type NextFetchInit = RequestInit & { next?: { revalidate?: number } };

const CRM_URL = process.env.CRM_URL ?? 'https://crm-nadlan.vercel.app';
const API_KEY = process.env.PROPSTORY_API_KEY ?? '';

export interface CmsArticle {
  id: string;
  title: string;
  slug: string;
  excerpt: string | null;
  content: string;
  tags: string[];
  image_url: string | null;
  published_at: string | null;
  created_at: string;
}

export async function fetchCmsArticles(): Promise<CmsArticle[]> {
  try {
    const res = await fetch(`${CRM_URL}/api/propstory/articles?limit=20`, {
      headers: { 'x-api-key': API_KEY },
      next: { revalidate: 300 },
    } as NextFetchInit);
    if (!res.ok) return [];
    const data = await res.json();
    return data.articles ?? [];
  } catch {
    return [];
  }
}

export async function fetchCmsArticle(slug: string): Promise<CmsArticle | null> {
  try {
    const res = await fetch(`${CRM_URL}/api/propstory/articles?slug=${encodeURIComponent(slug)}`, {
      headers: { 'x-api-key': API_KEY },
      next: { revalidate: 300 },
    } as NextFetchInit);
    if (!res.ok) return null;
    const data = await res.json();
    return data.article ?? null;
  } catch {
    return null;
  }
}

// Convert plain markdown from BlogPilot to simple HTML for rendering
export function mdToHtml(md: string): string {
  return md
    .replace(/^### (.+)$/gm, '<h3 class="text-xl font-bold text-slate-900 mt-8 mb-3">$1</h3>')
    .replace(/^## (.+)$/gm, '<h2 class="text-2xl font-bold text-slate-900 mt-10 mb-4">$1</h2>')
    .replace(/^# (.+)$/gm, '<h1 class="text-3xl font-black text-slate-900 mt-0 mb-6">$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/^[-*] (.+)$/gm, '<li class="mb-1">$1</li>')
    .replace(/(<li[^>]*>.*<\/li>\n?)+/g, (m) => `<ul class="list-disc list-inside space-y-1 my-4 text-slate-700">${m}</ul>`)
    .replace(/\n\n(?!<[hul])/g, '</p><p class="text-slate-700 leading-relaxed mb-5">')
    .replace(/^(?!<[hul])/, '<p class="text-slate-700 leading-relaxed mb-5">')
    .replace(/$/, '</p>')
    .replace(/<p[^>]*>\s*<\/p>/g, '');
}
